<?php
/** Slice 2 proof — the upload in parts (spec "Proof" 1–6): a 20 MB file in three parts, resume, missing parts, dedupe, the same-name conflict both ways, the ceiling, the quota, an empty file, an executable renamed .pdf, the one-request document_upload, an agent's, a guest's. */
require __DIR__ . '/lib.php';
$seed = seed_store();
$contracts = $seed['contracts'];
$priyaRoot = root_of(26);
$big = tmpfile_of(20 * 1048576, 'big', 'board-pack.bin');
$sha = hash_file('sha256', $big);

echo "1. A 20 MB file in parts\n";
$used0 = (int) one('SELECT used_bytes FROM libraries WHERE id = (SELECT library_id FROM folders WHERE id = :f)', ['f' => $contracts]);
$u = upload_file(27, $contracts, $big);
ok($u['start']['code'] === 200 && (int) $u['start']['json']['parts_total'] === 3 && (int) $u['start']['json']['part_bytes'] === 8388608, 'start: three parts of 8 MB (' . $u['start']['code'] . ')' . ($u['start']['code'] !== 200 ? ' ' . $u['start']['body'] : ''));
ok(count($u['parts']) === 3 && $u['parts'][3]['code'] === 200 && (int) $u['parts'][3]['json']['parts_done'] === 3, 'three parts received, parts_done 3');
ok($u['finish']['code'] === 200 && ($u['finish']['json']['ok'] ?? false) === true && (int) ($u['finish']['json']['version_no'] ?? 0) === 1 && ($u['finish']['json']['location'] ?? '') === '/documents/' . $u['finish']['json']['record_id'] . '?notice=uploaded', 'finish: version 1, location ends in the document id (' . $u['finish']['code'] . ' ' . substr($u['finish']['body'], 0, 200) . ')');
$bigId = (int) ($u['finish']['json']['record_id'] ?? 0);
$d = doc_row($bigId);
ok($d !== null && $d['sha256'] === $sha && (int) $d['byte_size'] === 20 * 1048576 && $d['mime_kind'] === 'other' && (int) $d['owner_member_id'] === 27, 'the document: the file\'s sha256, 20 MB, kind other, owned by the uploader');
$blob = q('SELECT * FROM blobs WHERE sha256 = :s', ['s' => $sha])[0] ?? null;
ok($blob !== null && (int) $blob['ref_count'] === 1 && is_file(store() . '/' . $blob['storage_path']) && $blob['storage_path'] === 'blobs/' . substr($sha, 0, 2) . '/' . substr($sha, 2, 2) . '/' . $sha, 'one blob under blobs/aa/bb/<sha>, ref_count 1, the file on disk');
ok(hash_file('sha256', store() . '/' . $blob['storage_path']) === $sha, 'the stored bytes hash to the same sha256 (assembled in order)');
ok(!is_dir(store() . '/uploads/' . $u['session']['session_id']), 'the parts directory is gone after the finish');
$used1 = (int) one('SELECT used_bytes FROM libraries WHERE id = (SELECT library_id FROM folders WHERE id = :f)', ['f' => $contracts]);
ok($used1 - $used0 === 20 * 1048576, 'the library counts 20 MB more');
ok((int) one("SELECT count(*) FROM activity_log WHERE action = 'document.upload' AND document_id = :d", ['d' => $bigId]) === 1 && (int) one("SELECT count(*) FROM activity_log WHERE action = 'upload.start' AND folder_id = :f", ['f' => $contracts]) >= 1, 'document.upload and upload.start logged with the ids');
$listing = get_json(26, '/f/' . $contracts)['json']['data']['listing']['rows'] ?? [];
ok(in_array('board-pack.bin', array_column($listing, 'name'), true), 'the folder lists it for a group member');

echo "2. The same bytes again, elsewhere\n";
$u2 = upload_file(26, $priyaRoot, $big, ['filename' => 'my-copy.bin']);
ok($u2['finish']['code'] === 200 && ($u2['finish']['json']['deduplicated'] ?? false) === true, 'the finish says deduplicated');
$blob = q('SELECT * FROM blobs WHERE sha256 = :s', ['s' => $sha])[0];
ok((int) $blob['ref_count'] === 2 && (int) one('SELECT count(*) FROM blobs WHERE sha256 = :s', ['s' => $sha]) === 1 && count(glob(store() . '/blobs/*/*/' . $sha)) === 1, 'one blob, ref_count 2, one file on disk');
$u3 = upload_file(26, $priyaRoot, $big, ['filename' => 'my-copy-2.bin', 'sha256' => $sha]);
ok($u3['start']['code'] === 200 && (int) $u3['start']['json']['parts_total'] === 0 && ($u3['start']['json']['deduplicated'] ?? false) === true && $u3['finish']['code'] === 200 && count($u3['parts']) === 0, 'a start naming a sha256 already stored needs no parts: parts_total 0, the finish at once');
ok((int) one('SELECT ref_count FROM blobs WHERE sha256 = :s', ['s' => $sha]) === 3, '...ref_count 3');

echo "3. Resume and missing parts\n";
$u4 = upload_file(27, $contracts, $big, ['filename' => 'resumed.bin', 'skip_parts' => [2]]);
ok($u4['finish']['code'] === 422 && ($u4['finish']['json']['error']['code'] ?? '') === 'missing_parts' && ($u4['finish']['json']['error']['missing'] ?? []) === [2] && str_contains($u4['finish']['json']['error']['message'] ?? '', 'Part 2 missing'), 'a finish with part 2 missing: 422 missing_parts {missing: [2]}');
$sid = (int) $u4['session']['session_id'];
$bytes2 = file_get_contents($big, false, null, 8388608, 8388608);
$p = post_raw(27, '/upload/part?session=' . $sid . '&n=2', $bytes2);
$p = post_raw(27, '/upload/part?session=' . $sid . '&n=2', $bytes2);
ok($p['code'] === 200 && (int) $p['json']['parts_done'] === 3 && (int) one('SELECT count(*) FROM upload_parts WHERE session_id = :s AND part_no = 2', ['s' => $sid]) === 1, 'part 2 sent twice (a resume): one row, parts_done 3');
$bad = post_raw(27, '/upload/part?session=' . $sid . '&n=4', 'xx');
ok($bad['code'] === 422 && ($bad['json']['error']['code'] ?? '') === 'bad_part', 'a part beyond parts_total: 422 bad_part');
$bad = post_raw(27, '/upload/part?session=' . $sid . '&n=1', 'short');
ok($bad['code'] === 422 && str_contains($bad['json']['error']['message'] ?? '', 'expected'), 'a part of the wrong size: 422 with the expected size');
$other = post_raw(26, '/upload/part?session=' . $sid . '&n=1', $bytes2);
ok($other['code'] === 404, 'another member sending a part to my session: 404');
$f = post_j(27, '/upload/finish', ['session' => $sid]);
ok($f['code'] === 200 && (int) $f['json']['version_no'] === 1 && doc_row((int) $f['json']['record_id'])['sha256'] === $sha, 'the finish succeeds after the resume; the same bytes → the same sha256 (deduplicated again)');

echo "4. The same name: 409, then a version, then keep both\n";
$small = tmpfile_of(3000, 'small', 'acme-msa.pdf');
$c = upload_file(27, $contracts, $small);
ok($c['start']['code'] === 409 && ($c['start']['json']['error']['code'] ?? '') === 'name_taken' && (int) ($c['start']['json']['error']['existing_document_id'] ?? 0) === $seed['board_doc'], 'a same-named upload is refused at the start: 409 name_taken with existing_document_id');
$v = upload_file(27, $contracts, $small, ['document_id' => $seed['board_doc']]);
ok($v['finish']['code'] === 200 && (int) $v['finish']['json']['version_no'] === 2 && ($v['finish']['json']['new_document'] ?? true) === false, 'restarted with document_id: version 2 of the existing document');
ok((int) one('SELECT current_version_id = (SELECT id FROM document_versions WHERE document_id = :d AND version_no = 2) FROM documents WHERE id = :d', ['d' => $seed['board_doc']]) === 1 && (int) one('SELECT count(*) FROM document_versions WHERE document_id = :d AND purged_at IS NULL', ['d' => $seed['board_doc']]) === 2, '...it is current; version 1 stays restorable');
ok((int) one("SELECT count(*) FROM activity_log WHERE action = 'document.version' AND document_id = :d", ['d' => $seed['board_doc']]) === 1, 'logged document.version');
$kb = upload_file(27, $contracts, $small, ['mode' => 'keep_both']);
ok($kb['finish']['code'] === 200 && ($kb['finish']['json']['name'] ?? '') === 'acme-msa (2).pdf' && ($kb['finish']['json']['new_document'] ?? false) === true, 'restarted with mode keep_both: a new document "acme-msa (2).pdf"');
$race = post_j(27, '/upload/start', ['folder_id' => $contracts, 'filename' => 'late.pdf', 'byte_size' => 3000]);
pdo()->exec("SELECT set_config('app.member_id', '27', false)");
$sidr = (int) $race['json']['session_id'];
post_raw(27, '/upload/part?session=' . $sidr . '&n=1', file_get_contents($small));
$lateId = q('SELECT document_id FROM dc_version_add(NULL, :f, :n, (SELECT blob_id FROM dc_blob_claim(:s, 10)), :n, :m, 10, :s, 27)', ['f' => $contracts, 'n' => 'late.pdf', 's' => hash('sha256', 'late'), 'm' => 'application/pdf'])[0]['document_id'];
$f = post_j(27, '/upload/finish', ['session' => $sidr]);
ok($f['code'] === 409 && ($f['json']['error']['code'] ?? '') === 'name_taken' && (int) $f['json']['error']['existing_document_id'] === (int) $lateId, 'a name taken between the start and the finish: 409 at the finish, the session kept');
$f = post_j(27, '/upload/finish', ['session' => $sidr, 'conflict' => 'keep_both']);
ok($f['code'] === 200 && ($f['json']['name'] ?? '') === 'late (2).pdf', '...answered with conflict keep_both: "late (2).pdf"');
ok((int) one("SELECT count(*) FROM activity_log WHERE action = 'upload.conflict'") >= 1, 'upload.conflict logged');

echo "5. Refusals\n";
$r = post_j(27, '/upload/start', ['folder_id' => $contracts, 'filename' => 'huge.bin', 'byte_size' => 3 * 1024 * 1024 * 1024]);
ok($r['code'] === 200 && (int) $r['json']['parts_total'] === 384, 'a 3 GB file starts: no per-file ceiling by default (db/024) — 384 parts');
pdo()->exec("UPDATE upload_sessions SET status = 'expired' WHERE id = " . (int) ($r['json']['session_id'] ?? 0));
pdo()->exec('UPDATE dc_settings SET max_document_bytes = 2147483648');
$r = post_j(27, '/upload/start', ['folder_id' => $contracts, 'filename' => 'huge.bin', 'byte_size' => 3 * 1024 * 1024 * 1024]);
ok($r['code'] === 413 && ($r['json']['error']['code'] ?? '') === 'too_large' && str_contains($r['json']['error']['message'] ?? '', 'at most'), 'over a ceiling an admin set: 413 too_large in words');
pdo()->exec('UPDATE dc_settings SET max_document_bytes = NULL');
$r = post_j(27, '/upload/start', ['folder_id' => $contracts, 'filename' => 'empty.txt', 'byte_size' => 0]);
ok($r['code'] === 422 && ($r['json']['error']['code'] ?? '') === 'empty', 'a zero-byte file: 422 empty');
pdo()->exec('UPDATE libraries SET quota_bytes = used_bytes + 1000 WHERE id = (SELECT library_id FROM folders WHERE id = ' . $contracts . ')');
$r = post_j(27, '/upload/start', ['folder_id' => $contracts, 'filename' => 'over.bin', 'byte_size' => 5000]);
ok($r['code'] === 422 && ($r['json']['error']['code'] ?? '') === 'quota' && str_contains($r['json']['error']['message'] ?? '', 'quota'), 'over the quota: 422 quota');
pdo()->exec('UPDATE libraries SET quota_bytes = NULL');
ok((int) one("SELECT count(*) FROM activity_log WHERE action = 'upload.refused' AND after->>'code' IN ('too_large', 'quota', 'empty')") === 3, 'every refusal logged upload.refused with its code');
$exe = tmpfile_of(4000, 'exe', 'invoice.pdf');
file_put_contents($exe, "MZ\x90\x00" . substr(file_get_contents($exe), 4));
$e = upload_file(27, $contracts, $exe);
$exeId = (int) ($e['finish']['json']['record_id'] ?? 0);
$ed = doc_row($exeId);
ok($e['finish']['code'] === 200 && $ed !== null && $ed['mime_kind'] === 'other' && ($e['finish']['json']['inline_ok'] ?? true) === false, 'an executable renamed .pdf is stored as other, never inline');
$r = post_j(28, '/upload/start', ['folder_id' => $contracts, 'filename' => 'bea.txt', 'byte_size' => 10]);
ok($r['code'] === 404, 'a member outside the group cannot start an upload there (404)');
pdo()->exec("INSERT INTO folder_access (folder_id, principal_kind, principal_id, level, granted_by) VALUES ($contracts, 'member', 28, 'view', 27) ON CONFLICT DO NOTHING");
$r = post_j(28, '/upload/start', ['folder_id' => $contracts, 'filename' => 'bea.txt', 'byte_size' => 10]);
ok($r['code'] === 403, 'a viewer of the folder cannot upload (403 in words: too little — slice 1\'s rule)');
$r = post_j(29, '/upload/start', ['folder_id' => $contracts, 'filename' => 'ann.txt', 'byte_size' => 10]);
ok($r['code'] === 404 || $r['code'] === 403, 'a guest: refused');

echo "6. The one-request document_upload\n";
$txt = fx_write('notes-one.txt', fx_para(5, 2000));
$r = post_file(27, '/documents/upload.php', ['folder' => $contracts], $txt);
$oneId = (int) ($r['json']['record_id'] ?? 0);
ok($r['code'] === 200 && $oneId > 0 && ($r['json']['location'] ?? '') === '/documents/' . $oneId . '?notice=uploaded' && doc_row($oneId)['mime_type'] === 'text/plain', 'document_upload (multipart) makes a document: record_id and location (' . $r['code'] . ')');
$r = post_file(27, '/documents/upload.php', ['folder' => $contracts], $txt);
ok($r['code'] === 200 && (int) $r['json']['version_no'] === 2 && (int) $r['json']['record_id'] === $oneId, 'the same file again: a new version by default (on_conflict version)');
$r = post_file(27, '/documents/upload.php', ['folder' => $contracts, 'on_conflict' => 'refuse'], $txt);
ok($r['code'] === 409, 'on_conflict refuse: 409');
$r = post_file(27, '/documents/upload.php', ['folder' => $contracts, 'on_conflict' => 'keep_both'], $txt);
ok($r['code'] === 200 && ($r['json']['name'] ?? '') === 'notes-one (2).txt', 'on_conflict keep_both: "notes-one (2).txt"');
$r = post_agent(40, 901, '/documents/upload.php', ['folder' => $contracts, 'file_base64' => base64_encode("agent bytes\n" . fx_para(9, 500)), 'filename' => 'from-agent.txt']);
$agentId = (int) ($r['json']['record_id'] ?? 0);
ok($r['code'] === 200 && $agentId > 0 && (int) doc_row($agentId)['owner_member_id'] === 40 && one("SELECT source FROM document_versions WHERE document_id = :d", ['d' => $agentId]) === 'agent', 'an agent uploads with file_base64 under its run token: the document is the agent\'s, source agent');
$ev = last_event('document.upload');
ok($ev['source'] === 'agent' && (int) $ev['agent_run_id'] === 901, '...logged with source agent and the run id');
$r = post_j(29, '/documents/upload.php', ['folder' => $contracts, 'file_base64' => base64_encode('x'), 'filename' => 'g.txt']);
ok(in_array($r['code'], [403, 404], true), 'a guest\'s document_upload: refused');
$r = post_j(27, '/documents/upload.php', ['folder' => $contracts]);
ok($r['code'] === 422 && ($r['json']['error']['fields']['file'] ?? '') !== '', 'no file: 422 on the file field');
ok((int) one("SELECT count(*) FROM activity_log WHERE (after->>'filename') IS NOT NULL AND length(after->>'filename') > 120") === 0, 'no logged filename is longer than 120 characters');
finish();
